#!/usr/bin/env python3
"""A small, persistent HTTP key-value service."""

from __future__ import annotations

import argparse
import json
import math
import os
import re
import signal
import tempfile
import threading
import time
import urllib.parse
from dataclasses import dataclass
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from pathlib import Path
from typing import Any


MAX_BODY_BYTES = 1024 * 1024
_BAD_PERCENT_ESCAPE = re.compile(r"%(?![0-9A-Fa-f]{2})")


class StoreError(Exception):
    """Raised when the on-disk store cannot be loaded or saved."""


@dataclass
class Entry:
    value: Any
    expires_at: float | None


def _reject_json_constant(value: str) -> None:
    raise ValueError(f"non-standard JSON number: {value}")


class Store:
    def __init__(self, path: Path):
        self.path = path
        self.lock = threading.RLock()
        self.entries: dict[str, Entry] = {}
        self._load()

    @staticmethod
    def _valid_key(key: Any) -> bool:
        return isinstance(key, str) and bool(key) and "/" not in key

    def _load(self) -> None:
        try:
            raw = self.path.read_bytes()
        except FileNotFoundError:
            self.path.parent.mkdir(parents=True, exist_ok=True)
            self._persist_locked()
            return
        except OSError as exc:
            raise StoreError(f"cannot read data file {self.path}: {exc}") from exc

        try:
            document = json.loads(raw, parse_constant=_reject_json_constant)
            records = document["entries"]
            if set(document) != {"version", "entries"} or document["version"] != 1:
                raise ValueError("unsupported data-file format")
            if not isinstance(records, dict):
                raise ValueError("entries must be an object")

            loaded: dict[str, Entry] = {}
            now = time.time()
            removed_expired = False
            for key, record in records.items():
                if not self._valid_key(key):
                    raise ValueError("invalid stored key")
                if not isinstance(record, dict) or set(record) != {"value", "expires_at"}:
                    raise ValueError(f"invalid entry for key {key!r}")
                expires_at = record["expires_at"]
                if expires_at is not None and (
                    isinstance(expires_at, bool)
                    or not isinstance(expires_at, (int, float))
                    or not math.isfinite(expires_at)
                ):
                    raise ValueError(f"invalid expiry for key {key!r}")
                if expires_at is not None and expires_at <= now:
                    removed_expired = True
                    continue
                loaded[key] = Entry(record["value"], expires_at)
        except (UnicodeDecodeError, json.JSONDecodeError, TypeError, ValueError, KeyError) as exc:
            raise StoreError(f"invalid data file {self.path}: {exc}") from exc

        self.entries = loaded
        if removed_expired:
            self._persist_locked()

    def _document(self) -> dict[str, Any]:
        return {
            "version": 1,
            "entries": {
                key: {"value": entry.value, "expires_at": entry.expires_at}
                for key, entry in self.entries.items()
            },
        }

    def _persist_locked(self) -> None:
        directory = self.path.parent
        directory.mkdir(parents=True, exist_ok=True)
        temporary_name: str | None = None
        try:
            fd, temporary_name = tempfile.mkstemp(
                prefix=f".{self.path.name}.", suffix=".tmp", dir=directory
            )
            with os.fdopen(fd, "w", encoding="utf-8") as stream:
                json.dump(
                    self._document(),
                    stream,
                    ensure_ascii=False,
                    allow_nan=False,
                    separators=(",", ":"),
                    sort_keys=True,
                )
                stream.write("\n")
                stream.flush()
                os.fsync(stream.fileno())
            os.replace(temporary_name, self.path)
            temporary_name = None
            try:
                directory_fd = os.open(directory, os.O_RDONLY)
                try:
                    os.fsync(directory_fd)
                finally:
                    os.close(directory_fd)
            except OSError:
                # Some filesystems do not permit syncing a directory. The file
                # itself has still been synced and atomically installed.
                pass
        except (OSError, TypeError, ValueError) as exc:
            raise StoreError(f"cannot persist data file {self.path}: {exc}") from exc
        finally:
            if temporary_name is not None:
                try:
                    os.unlink(temporary_name)
                except FileNotFoundError:
                    pass

    def _purge_expired_locked(self) -> bool:
        now = time.time()
        expired = [
            key
            for key, entry in self.entries.items()
            if entry.expires_at is not None and entry.expires_at <= now
        ]
        for key in expired:
            del self.entries[key]
        if expired:
            self._persist_locked()
        return bool(expired)

    def put(self, key: str, value: Any, ttl_seconds: int | float | None) -> bool:
        with self.lock:
            self._purge_expired_locked()
            created = key not in self.entries
            old_entry = self.entries.get(key)
            expires_at = None if ttl_seconds is None else time.time() + ttl_seconds
            self.entries[key] = Entry(value, expires_at)
            try:
                self._persist_locked()
            except StoreError:
                if old_entry is None:
                    del self.entries[key]
                else:
                    self.entries[key] = old_entry
                raise
            return created

    def get(self, key: str) -> tuple[bool, Any]:
        with self.lock:
            self._purge_expired_locked()
            entry = self.entries.get(key)
            return (False, None) if entry is None else (True, entry.value)

    def delete(self, key: str) -> bool:
        with self.lock:
            self._purge_expired_locked()
            old_entry = self.entries.pop(key, None)
            if old_entry is None:
                return False
            try:
                self._persist_locked()
            except StoreError:
                self.entries[key] = old_entry
                raise
            return True

    def keys(self) -> list[str]:
        with self.lock:
            self._purge_expired_locked()
            return sorted(self.entries)


class KVHTTPServer(ThreadingHTTPServer):
    daemon_threads = True
    allow_reuse_address = True

    def __init__(self, address: tuple[str, int], store: Store):
        self.store = store
        super().__init__(address, RequestHandler)


class RequestHandler(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"
    server_version = "PersistentKV/1.0"

    @property
    def store(self) -> Store:
        return self.server.store  # type: ignore[attr-defined,no-any-return]

    def __getattr__(self, name: str) -> Any:
        # BaseHTTPRequestHandler looks up do_<METHOD> dynamically. Handling the
        # fallback here keeps even unusual unsupported methods in JSON.
        if name.startswith("do_"):
            return self._dispatch
        raise AttributeError(name)

    def log_message(self, format: str, *args: Any) -> None:
        super().log_message(format, *args)

    def send_error(
        self,
        code: int,
        message: str | None = None,
        explain: str | None = None,
    ) -> None:
        # Parsing errors raised by BaseHTTPRequestHandler also need a JSON body.
        if code == 501:
            code = 405
        self._send_json(
            code,
            {"error": {"code": "http_error", "message": message or "HTTP error"}},
        )

    def handle_expect_100(self) -> bool:
        length = self.headers.get("Content-Length")
        if length is not None:
            try:
                if int(length) > MAX_BODY_BYTES:
                    self.close_connection = True
                    self._error(413, "body_too_large", "request body exceeds 1 MiB")
                    return False
            except ValueError:
                self.close_connection = True
                self._error(400, "invalid_content_length", "invalid Content-Length")
                return False
        return super().handle_expect_100()

    def _send_json(self, status: int, payload: Any | None = None) -> None:
        body = b"" if payload is None else json.dumps(
            payload, ensure_ascii=False, allow_nan=False, separators=(",", ":")
        ).encode("utf-8")
        self.send_response(status)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(body)))
        self.send_header("Cache-Control", "no-store")
        self.end_headers()
        if self.command != "HEAD" and body:
            try:
                self.wfile.write(body)
            except (BrokenPipeError, ConnectionResetError):
                pass

    def _error(self, status: int, code: str, message: str) -> None:
        self._send_json(status, {"error": {"code": code, "message": message}})

    def _decode_key(self, encoded: str) -> str | None:
        if not encoded or _BAD_PERCENT_ESCAPE.search(encoded):
            self._error(400, "invalid_key", "key is empty or incorrectly encoded")
            return None
        try:
            key = urllib.parse.unquote_to_bytes(encoded).decode("utf-8", errors="strict")
        except UnicodeDecodeError:
            self._error(400, "invalid_key", "key must be valid UTF-8")
            return None
        if not Store._valid_key(key):
            self._error(400, "invalid_key", "key must be non-empty and cannot contain '/'" )
            return None
        return key

    def _read_json_body(self) -> Any | None:
        transfer_encoding = self.headers.get("Transfer-Encoding")
        lengths = self.headers.get_all("Content-Length", failobj=[])
        if transfer_encoding is not None:
            self.close_connection = True
            self._error(400, "unsupported_transfer_encoding", "Transfer-Encoding is not supported")
            return None
        if len(lengths) != 1:
            self.close_connection = True
            self._error(400, "invalid_content_length", "exactly one Content-Length is required")
            return None
        try:
            length = int(lengths[0], 10)
        except ValueError:
            self.close_connection = True
            self._error(400, "invalid_content_length", "invalid Content-Length")
            return None
        if length < 0:
            self.close_connection = True
            self._error(400, "invalid_content_length", "invalid Content-Length")
            return None
        if length > MAX_BODY_BYTES:
            self.close_connection = True
            self._error(413, "body_too_large", "request body exceeds 1 MiB")
            return None
        raw = self.rfile.read(length)
        if len(raw) != length:
            self.close_connection = True
            self._error(400, "incomplete_body", "request body is incomplete")
            return None
        try:
            text = raw.decode("utf-8", errors="strict")
            return json.loads(text, parse_constant=_reject_json_constant)
        except (UnicodeDecodeError, json.JSONDecodeError, ValueError):
            self._error(400, "malformed_json", "request body must be valid JSON")
            return None

    def _dispatch(self) -> None:
        parsed = urllib.parse.urlsplit(self.path)
        path = parsed.path
        method = self.command

        if path == "/health":
            if method != "GET":
                self._method_not_allowed(["GET"])
            else:
                self._send_json(200, {"status": "ok"})
            return

        if path == "/v1/keys":
            if method != "GET":
                self._method_not_allowed(["GET"])
                return
            try:
                keys = self.store.keys()
            except StoreError as exc:
                self.log_error("%s", exc)
                self._error(500, "storage_error", "could not persist store state")
                return
            self._send_json(200, {"keys": keys})
            return

        prefix = "/v1/kv/"
        if path.startswith(prefix):
            key = self._decode_key(path[len(prefix):])
            if key is None:
                return
            if method == "GET":
                self._get_key(key)
            elif method == "PUT":
                self._put_key(key)
            elif method == "DELETE":
                self._delete_key(key)
            else:
                self._method_not_allowed(["GET", "PUT", "DELETE"])
            return

        self._error(404, "not_found", "route not found")

    def _method_not_allowed(self, allowed: list[str]) -> None:
        body = json.dumps(
            {"error": {"code": "method_not_allowed", "message": "method not allowed"}},
            separators=(",", ":"),
        ).encode("utf-8")
        self.send_response(405)
        self.send_header("Allow", ", ".join(allowed))
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(body)))
        self.send_header("Cache-Control", "no-store")
        self.end_headers()
        if self.command != "HEAD":
            self.wfile.write(body)

    def _get_key(self, key: str) -> None:
        try:
            found, value = self.store.get(key)
        except StoreError as exc:
            self.log_error("%s", exc)
            self._error(500, "storage_error", "could not persist store state")
            return
        if not found:
            self._error(404, "not_found", "key not found")
            return
        self._send_json(200, {"key": key, "value": value})

    def _put_key(self, key: str) -> None:
        body = self._read_json_body()
        if body is None:
            return
        if not isinstance(body, dict) or "value" not in body or not set(body) <= {"value", "ttl_seconds"}:
            self._error(
                400,
                "invalid_body",
                "body must be an object containing value and optional ttl_seconds",
            )
            return
        ttl = body.get("ttl_seconds")
        if "ttl_seconds" in body and (
            isinstance(ttl, bool)
            or not isinstance(ttl, (int, float))
            or not math.isfinite(ttl)
            or ttl <= 0
        ):
            self._error(400, "invalid_ttl", "ttl_seconds must be a finite number greater than zero")
            return
        try:
            created = self.store.put(key, body["value"], ttl)
        except StoreError as exc:
            self.log_error("%s", exc)
            self._error(500, "storage_error", "could not persist store state")
            return
        self._send_json(201 if created else 200, {"key": key, "value": body["value"]})

    def _delete_key(self, key: str) -> None:
        try:
            deleted = self.store.delete(key)
        except StoreError as exc:
            self.log_error("%s", exc)
            self._error(500, "storage_error", "could not persist store state")
            return
        if not deleted:
            self._error(404, "not_found", "key not found")
            return
        self._send_json(204)


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser(description="Persistent HTTP key-value service")
    parser.add_argument("--host", required=True, help="address to listen on")
    parser.add_argument("--port", required=True, type=int, help="TCP port (0 chooses a free port)")
    parser.add_argument("--data", required=True, type=Path, help="JSON persistence file")
    args = parser.parse_args()
    if not 0 <= args.port <= 65535:
        parser.error("--port must be between 0 and 65535")
    return args


def main() -> int:
    args = parse_args()
    try:
        store = Store(args.data)
        server = KVHTTPServer((args.host, args.port), store)
    except (OSError, StoreError) as exc:
        print(f"startup failed: {exc}", file=os.sys.stderr, flush=True)
        return 1

    def stop_server(signum: int, frame: Any) -> None:
        raise KeyboardInterrupt

    signal.signal(signal.SIGTERM, stop_server)
    signal.signal(signal.SIGINT, stop_server)
    print(f"LISTENING {server.server_address[1]}", flush=True)
    try:
        server.serve_forever(poll_interval=0.1)
    except KeyboardInterrupt:
        pass
    finally:
        server.server_close()
    return 0


if __name__ == "__main__":
